import { Header } from "@/components/layout/Header";
import { ReactNode } from "react";
import CheckoutStages from "./_components/CheckoutProgress";

export const metadata = {
  title: "Checkout | Fashion Friday",
  description:
    "Complete your order quickly and securely at Fashion Friday. Enter shipping details, choose payment, and confirm your purchase.",
  openGraph: {
    title: "Checkout | Fashion Friday",
    description:
      "Fast, secure, and simple checkout process for Fashion Friday customers.",
    type: "website",
    url: "https://www.fashionfriday.in/checkout",
  },
};

export default function CheckoutLayout({ children }: { children: ReactNode }) {
  return (
    <div>
      <div className="fixed top-0 right-0">
        <Header/>
        <CheckoutStages currentStage={2} />
      </div>
      <main>{children}</main>
    </div>
  );
}
